\textbf{\textcolor{red}{Worked example --- QL with symmetric externality.}}

\textbf{\textcolor{red}{0. Setup.}}
\[ \max\;\; \bigl(\ln y^1 + x^1 - y^2\bigr) + \bigl(\ln y^2 + x^2 - y^1\bigr) \;\;\text{sub.}\;\; x^1 + x^2 \le \omega_x,\;\; y^1 + y^2 \le \omega_y. \]
Each agent's $-y^j$ term is the \emph{negative spillover} from the other agent's $y$. \textbf{Symmetric} $\Rightarrow \lambda = 1/2$, so $x^i$ will not be pinned down by the FOC.

\textbf{\textcolor{red}{1. Lagrangian \& FOCs.}}
\[ \mathcal{L} = \sum_i\bigl[\ln y^i + x^i - y^{-i}\bigr] + \mu_x(\omega_x - x^1 - x^2) + \mu_y(\omega_y - y^1 - y^2). \]

$\bullet$ $\partial_{x_i}\mathcal{L}: \; 1 - \mu_x = 0 \;\Rightarrow\; \mu_x = 1$. \;\; (by symmetry, $i = 1, 2$)

$\bullet$ $\partial_{y_i}\mathcal{L}: \; \dfrac{1}{y^i} - 1 - \mu_y = 0 \;\Rightarrow\; \dfrac{1}{y^i} = 1 + \mu_y$.

\textbf{\textcolor{red}{2. Rearrange.}}
\[ \boxed{\;\; y^i \;=\; \dfrac{1}{1 + \mu_y}. \;\;}\quad[\square] \]

\textbf{\textcolor{red}{3. Sub in the resource constraint  $y^1 + y^2 = \omega_y$  (does $\mu_y$ bind?).}}
\[ \dfrac{2}{1 + \mu_y} = \omega_y. \quad[\triangle] \]

\textbf{\textcolor{red}{4. Cases.}}

$\bullet$ \textbf{$\mu_y > 0$ iff $\omega_y < 2$.} Say $\omega_y = 1$: from $[\triangle]$, $\mu_y = 1$; sub in $[\square]$, $\boxed{\;y^i = 0.5.\;}$

$\bullet$ \textbf{$\mu_y = 0$ iff $\omega_y \ge 2$.} Say $\omega_y = 3$: from $[\square]$, $y^i = 1$, so $\omega_y^{\text{used}} = 2$. \textcolor{red}{\emph{One unit destroyed!}} (no issue of saturation --- planner just chooses to use less because of the externality).

\textcolor{purple}{\emph{Reading.}} Even with abundant $\omega_y$, the planner stops at $y^i = 1$ because beyond that the social MB ($1/y^i - 1$) goes negative.

\textbf{\textcolor{blue}{Cross-refs:}} setup, QL asymmetric, CD symmetric, solutions.

\textbf{\textcolor{red}{Worked example --- Cobb--Douglas symmetric externality.}}

\textbf{\textcolor{red}{0. Setup.}}
\[ \max\;\; \sqrt{x^1\, y^1} + \sqrt{x^2\, y^2} - y^1 - y^2 \;\;\text{sub.}\;\; \sum_i x^i \le \omega_x,\;\; \sum_i y^i \le \omega_y. \]

\textbf{\textcolor{red}{1. Lagrangian.}}
\[ \mathcal{L} = \sum_i\bigl[\sqrt{x^i y^i} - y^{-i}\bigr] + \mu_x(\omega_x - \textstyle\sum x^i) + \mu_y(\omega_y - \textstyle\sum y^i). \]

\textbf{\textcolor{red}{2. FOCs} \;($i = 1, 2$).}

$\bullet$ $\partial_{x_i}\mathcal{L}: \; \dfrac{1}{2}\sqrt{\dfrac{y^i}{x^i}} - \mu_x = 0$.

$\bullet$ $\partial_{y_i}\mathcal{L}: \; \dfrac{1}{2}\sqrt{\dfrac{x^i}{y^i}} - 1 - \mu_y = 0$.

\textbf{\textcolor{red}{3. Rearrange.}}
\[ x^i = \dfrac{y^i}{4\,\mu_x^2}\quad[1],\qquad y^i = \dfrac{x^i}{4\,(1 + \mu_y)^2}\quad[2]. \]

\textbf{\textcolor{red}{4. Sub [2] in $\omega_y = y^1 + y^2$.}}
\[ \mu_y = \dfrac{1}{2}\sqrt{\dfrac{\omega_x}{\omega_y}} - 1\quad\text{hence:} \]

$\bullet$ $\mu_y > 0$ if $\omega_x/\omega_y > 4$. Say $\omega_x/\omega_y = 5 \Rightarrow \mu_y = 0.5\sqrt{5} - 1 \approx 0.12$  (binds).

$\bullet$ $\mu_y = 0$ if $\omega_x/\omega_y \le 4$ \;$\Rightarrow$\; $y^i = x^i/4$ and $y^1 + y^2 = \omega_x/4$, destroying all $\omega_y - \omega_x/4$.

\textbf{\textcolor{red}{5. Multiplier relations.}}
From [1]: $x^1 + x^2 = \omega_x$, then $\mu_x = \tfrac{1}{2}\sqrt{\omega_y/\omega_x}$.

Cross-check: $\mu_x\,(1 + \mu_y) = \tfrac{1}{4}$ \;\;(multiplier identity).

\textcolor{orange}{\emph{The CD case parallels QL but with an interior split between $x$ and $y$ governed by the $\omega_x/\omega_y$ ratio.}}

